def resolve(path, cwd, links):
    # Start with the initial path
    if path.startswith('/'):
        current = '/'
        remaining = path[1:]
    else:
        current = cwd
        remaining = path

    # Track number of symlinks followed
    link_count = 0
    max_links = 8

    # Split remaining path into components and process
    while remaining:
        # Split by '/', filter empty strings and '.'
        components = [c for c in remaining.split('/') if c and c != '.']
        remaining = ''

        for component in components:
            if component == '..':
                # Move to parent directory
                if current != '/':
                    current = current.rsplit('/', 1)[0]
                    if not current:
                        current = '/'
            else:
                # Append component to current path
                if current == '/':
                    candidate = '/' + component
                else:
                    candidate = current + '/' + component

                # Check if this is a symlink
                if candidate in links:
                    # Follow the symlink
                    link_count += 1
                    if link_count > max_links:
                        return None

                    target = links[candidate]

                    # Resolve target relative to the symlink's directory
                    if target.startswith('/'):
                        # Absolute symlink target
                        current = '/'
                        remaining = target[1:]
                    else:
                        # Relative symlink target
                        # Target is relative to the directory containing the symlink
                        if candidate == '/':
                            base = '/'
                        else:
                            base = candidate.rsplit('/', 1)[0]
                            if not base:
                                base = '/'

                        current = base
                        remaining = target

                    # Break to restart processing with new remaining path
                    break
                else:
                    # Not a symlink, just move to this path
                    current = candidate

    # Return the result
    if current == '/':
        return '/'
    else:
        return current

